                  required
                  style={{ width: "100%", padding: "8px", marginTop: "4px", minHeight: "80px" }}
                />
              </div>
              <button id="create-doc-btn" type="submit" style={{ padding: "8px 16px", cursor: "pointer" }}>Create Document</button>
